import XCTest
@testable import BarPathKit

/// Fixtures are generated by tools/make_fixtures.py (spec §6). Expected values are simulator
/// ground truth. Tests skip (not fail) when a fixture file has not been generated yet.
final class FixtureTests: XCTestCase {

    private func checkLiftFixture(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let recData = try fixtureData(name, "json")
        let expData = try fixtureData(name + ".expected", "json")
        let rec = try LiftRecording.decode(from: recData)
        let expected = try jsonObject(expData)
        let tol = expected["tolerance"] as? [String: Any] ?? [:]
        let tolHeight = number(tol["height"]) ?? 0.04
        let tolVelocity = number(tol["velocity"]) ?? 0.08
        let tolHorizontal = number(tol["horizontal"]) ?? 0.04

        let analysis = try LiftAnalyzer.analyze(rec)
        let m = analysis.metrics
        let ctx = "\(name): metrics=\(m) notes=\(analysis.notes) confidence=\(analysis.confidence)"

        if let v = number(expected["maxHeight"]) {
            XCTAssertEqual(m.maxHeight, v, accuracy: tolHeight, "maxHeight " + ctx, file: file, line: line)
        }
        if let v = number(expected["peakVerticalVelocity"]) {
            XCTAssertEqual(m.peakVerticalVelocity, v, accuracy: tolVelocity, "peakVerticalVelocity " + ctx,
                           file: file, line: line)
        }
        if let v = number(expected["catchHeight"]) {
            XCTAssertNotNil(m.catchHeight, "catchHeight " + ctx, file: file, line: line)
            if let c = m.catchHeight {
                XCTAssertEqual(c, v, accuracy: tolHeight, "catchHeight " + ctx, file: file, line: line)
            }
        }
        if let v = number(expected["finalHeight"]) {
            XCTAssertEqual(m.finalHeight, v, accuracy: tolHeight, "finalHeight " + ctx, file: file, line: line)
        }
        if let v = number(expected["maxBackward"]) {
            XCTAssertEqual(m.maxBackward, v, accuracy: tolHorizontal, "maxBackward " + ctx, file: file, line: line)
        }
        if let v = number(expected["maxForward"]) {
            XCTAssertEqual(m.maxForward, v, accuracy: tolHorizontal, "maxForward " + ctx, file: file, line: line)
        }
    }

    func testSimSnatch() throws {
        try checkLiftFixture("sim_snatch")
    }

    func testSimCleanAndJerk() throws {
        try checkLiftFixture("sim_clean_and_jerk")
    }

    func testSimSnatchConjugateQuaternions() throws {
        try checkLiftFixture("sim_snatch_conjugate")
        // Same lift in the other quaternion convention must analyze identically (auto-detection).
        let a = try LiftAnalyzer.analyze(try LiftRecording.decode(from: try fixtureData("sim_snatch", "json")))
        let b = try LiftAnalyzer.analyze(try LiftRecording.decode(from: try fixtureData("sim_snatch_conjugate", "json")))
        XCTAssertFalse(b.notes.contains(LiftAnalyzer.noteGravityOnly))
        // Separately simulated (different noise), so compare loosely.
        XCTAssertEqual(a.metrics.maxHeight, b.metrics.maxHeight, accuracy: 0.04)
        XCTAssertEqual(a.metrics.peakVerticalVelocity, b.metrics.peakVerticalVelocity, accuracy: 0.08)
    }

    func testSimSessionDetector() throws {
        let csvData = try fixtureData("sim_session", "csv")
        let expected = try jsonObject(try fixtureData("sim_session.expected", "json"))
        guard let text = String(data: csvData, encoding: .utf8) else {
            return XCTFail("sim_session.csv is not UTF-8")
        }
        let parsed = try SessionCSV.parse(text)
        XCTAssertFalse(parsed.samples.isEmpty)

        let detector = OnlineLiftDetector()
        var lifts: [(homing: Double, end: Double, reason: EndReason)] = []
        for s in parsed.samples {
            if let e = detector.process(s), case .liftEnded(let h, let end, let reason) = e {
                lifts.append((homing: h, end: end, reason: reason))
            }
        }

        let tol = expected["tolerance"] as? [String: Any] ?? [:]
        let tolTime = number(tol["time"]) ?? 0.5
        let expectedLifts = expected["lifts"] as? [[String: Any]] ?? []
        let expectedCount: Int = Int(number(expected["liftCount"]) ?? Double(expectedLifts.count))
        let summary = lifts.map { "(homing \($0.homing), end \($0.end), \($0.reason.rawValue))" }.joined(separator: ", ")

        XCTAssertEqual(lifts.count, expectedCount, "detected lifts: \(summary)")
        for (i, exp) in expectedLifts.enumerated() where i < lifts.count {
            if let h = number(exp["homingTime"]) {
                XCTAssertEqual(lifts[i].homing, h, accuracy: tolTime, "lift \(i + 1) homing; detected: \(summary)")
            }
            if let e = number(exp["endTime"]) {
                XCTAssertEqual(lifts[i].end, e, accuracy: tolTime, "lift \(i + 1) end; detected: \(summary)")
            }
        }
    }
}
